import {tableGeometry,columnGeometry,zoomSteps} from './spider-layout.js?v=11';
import {cardArt,cardPath} from './spider-cards.js?v=11';
import {newGame,rankLabel,suitSymbol,movable,canMove,canDeal,move,deal,hint,snapshot,validState} from './spider-engine.js?v=7';
const $=s=>document.querySelector(s),SAVE='clicks:spider:v1';let state,history=[],elapsed=0,selected=null,suggested=null,message='',storageOK=true,motionOrigins=null,viewScale=1;
try{const saved=JSON.parse(localStorage.getItem(SAVE));if(validState(saved?.state)){state=saved.state;elapsed=Number.isFinite(saved.elapsed)?Math.max(0,saved.elapsed):0;history=Array.isArray(saved.history)?saved.history.slice(-120).filter(validState):[];}}catch{}
state??=newGame(Math.floor(Math.random()*4294967296));
const timeText=()=>`${Math.floor(elapsed/60)}:${String(elapsed%60).padStart(2,'0')}`;
function save(){try{localStorage.setItem(SAVE,JSON.stringify({state,history,elapsed}));}catch{storageOK=false;}}
function checkpoint(){history.push(snapshot(state));if(history.length>120)history.shift();}
function commit(){selected=null;suggested=null;message='';save();render();}
function cardName(c){return `${rankLabel(c.rank)} of ${c.suit==='S'?'spades':'hearts'}`;}
function layout(){
 const board=$('#board');board.style.removeProperty('column-gap');const scroll=$('.table-scroll'),style=getComputedStyle(scroll),available=scroll.clientWidth-parseFloat(style.paddingLeft)-parseFloat(style.paddingRight),gap=parseFloat(getComputedStyle(board).columnGap)||0;
 const geometry=tableGeometry(available,gap,board.classList.contains('wide'),viewScale);board.style.width=geometry.boardWidth+'px';board.style.columnGap=geometry.gap+'px';board.style.setProperty('--card-width',geometry.cardWidth+'px');board.style.setProperty('--card-height',geometry.cardHeight+'px');
 board.querySelectorAll('.column').forEach((col,i)=>{const positions=columnGeometry(state.columns[i],geometry);col.querySelectorAll('.card').forEach((card,j)=>card.style.setProperty('--top',positions.tops[j]+'px'));col.style.height=positions.height+'px';});$('#view-note').textContent=geometry.boardWidth>available+.5?'Scroll across to see every column':'Drag or tap to move';
}
let layoutFrame=0,observedWidth=0;
function scheduleLayout(){cancelAnimationFrame(layoutFrame);layoutFrame=requestAnimationFrame(()=>{if(dragging){dragging=null;clearDrag();}$('#board').querySelectorAll('.card').forEach(c=>c.getAnimations().forEach(a=>a.cancel()));layout();});}
function cardPositions(){return new Map([...$('#board').querySelectorAll('.card')].map(c=>[c.dataset.cardId,{left:c.getBoundingClientRect().left,top:c.getBoundingClientRect().top,down:c.classList.contains('down')}]));}
function animateCards(old,cleared){
 if(!old.size||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 $('#board').querySelectorAll('.card').forEach(c=>{const p=old.get(c.dataset.cardId),r=c.getBoundingClientRect();if(p){const dx=p.left-r.left,dy=p.top-r.top;if(Math.abs(dx)+Math.abs(dy)>2)c.animate([{transform:'translate('+dx+'px,'+dy+'px)'},{transform:'translate(0,0)'}],{duration:210,easing:'cubic-bezier(.2,.7,.25,1)'});else if(p.down&&!c.classList.contains('down'))c.animate([{opacity:.3,transform:'rotateY(75deg)'},{opacity:1,transform:'rotateY(0)'}],{duration:240});}else c.animate([{opacity:.2,transform:'translateY(-15px)'},{opacity:1,transform:'translateY(0)'}],{duration:180});});
 if(state.completed.length>cleared)$('#completed .filled:last-child')?.animate([{transform:'scale(.8)',boxShadow:'0 0 24px #ffe182'},{transform:'scale(1)',boxShadow:'0 0 0 transparent'}],{duration:500});
}
function render(){
 const old=motionOrigins||cardPositions(),cleared=document.querySelectorAll("#completed .filled").length;motionOrigins=null;
 $('#score').textContent=state.score;$('#moves').textContent=state.moves;$('#time').textContent=timeText();$('#undo').disabled=!history.length;$('#hint').disabled=state.won;
 $('#deal').disabled=!state.stock.length||state.won;$('#deal-label').textContent=state.stock.length?`Deal · ${state.stock.length/10} left`:'Stock empty';$('.stock-packs').innerHTML=Array.from({length:state.stock.length/10},()=>'<i></i>').join('');
 $('#progress').textContent=`${state.completed.length} / 8`;$('#completed').innerHTML=Array.from({length:8},(_,i)=>{const c=state.completed[i]?.[0];return `<span class="${c?'filled '+(c.suit==='H'?'red':''):''}" aria-label="${c?'Completed '+(c.suit==='H'?'hearts':'spades'):'Empty sequence slot'}">${c?suitSymbol(c.suit):'·'}</span>`;}).join('');
 $('#board').innerHTML=state.columns.map((col,ci)=>`<div class="column ${suggested?.to===ci?'hint-target':''}" data-column="${ci}" style="height:calc(var(--card-height) + ${Math.max(0,col.length-1)} * var(--step))" role="group" aria-label="Column ${ci+1}, ${col.length} cards"><button class="empty-column" data-target="${ci}" aria-label="${col.length?'Move selected run to':'Empty column'} ${ci+1}" ${state.won?'disabled':''}>${col.length?'':'+'}</button>${col.map((c,i)=>`<button class="card ${!c.up?'down':c.suit==='H'?'red':''} ${selected?.column===ci&&selected.index===i?'selected':''} ${suggested?.from===ci&&suggested.index===i?'hint-source':''}" style="--index:${i};z-index:${i+1}" data-column="${ci}" data-index="${i}" data-card-id="${c.id}" aria-label="${c.up?cardName(c):'Face-down card'}, column ${ci+1}${c.up?(movable(state,ci,i)?', movable run':', blocked by cards below'):''}" ${c.up?`aria-pressed="${selected?.column===ci&&selected.index===i}"`:''} ${!c.up||state.won?'disabled':''} draggable="false" data-movable="${!state.won&&movable(state,ci,i)}">${c.up?`<span class="card-corner"><span>${rankLabel(c.rank)}</span><span>${suitSymbol(c.suit)}</span></span>${cardArt(c.rank,c.suit)}<span class="card-bottom" aria-hidden="true"><span>${rankLabel(c.rank)}</span><span>${suitSymbol(c.suit)}</span></span>`:''}</button>`).join('')}</div>`).join('');
 $('#message').textContent=!storageOK?'Browser storage is full. Progress cannot be saved.':message||(state.won?'Eight runs. Table cleared.':selected?`Selected ${rankLabel(state.columns[selected.column][selected.index].rank)}${suitSymbol(state.columns[selected.column][selected.index].suit)} run · choose a column.`:'');
 $('#win').hidden=!state.won;$('.table').classList.toggle('won',state.won);layout();animateCards(old,cleared);if(state.won)$('#win-detail').textContent=`${state.moves} moves · ${timeText()} · ${state.score} points`;
}
function choose(column,index){
 suggested=null;if(state.won)return;if(selected){if(column===selected.column&&index===selected.index){selected=null;message='';render();return;}if(canMove(state,selected.column,selected.index,column)){checkpoint();move(state,selected.column,selected.index,column);commit();return;}}
 if(movable(state,column,index)){selected={column,index};message='';}else message='Only a descending run in one suit can move together.';render();
}
$('#board').addEventListener('click',e=>{if(performance.now()<suppressClickUntil)return;const card=e.target.closest('[data-index]');if(card){choose(Number(card.dataset.column),Number(card.dataset.index));return;}const empty=e.target.closest('[data-target]');if(!empty)return;const to=Number(empty.dataset.target);if(selected&&canMove(state,selected.column,selected.index,to)){checkpoint();move(state,selected.column,selected.index,to);commit();}else{message=selected?'Place this run on the next higher rank, or an empty column.':'Select a card or matching-suit run first.';render();}});
let dragging=null,suppressClickUntil=0;
function clearDrag(){document.querySelectorAll('.drop-target,.drag-hidden').forEach(c=>c.classList.remove('drop-target','drag-hidden'));document.querySelector('.drag-ghost')?.remove();}
function dragGhost(run){
 const source=$('#board').querySelector('.card[data-column="'+run.column+'"][data-index="'+run.index+'"]'),r=source.getBoundingClientRect(),ghost=document.createElement('div');ghost.className='drag-ghost';ghost.setAttribute('aria-hidden','true');ghost.style.width=r.width+'px';ghost.style.setProperty('--card-width',r.width+'px');ghost.style.setProperty('--card-height',r.height+'px');ghost.style.setProperty('--ghost-font',getComputedStyle(source.querySelector('.card-corner')).fontSize);
 source.parentElement.querySelectorAll('.card').forEach(c=>{if(+c.dataset.index<run.index)return;const clone=c.cloneNode(true),rect=c.getBoundingClientRect();clone.classList.remove('selected','hint-source');clone.tabIndex=-1;clone.style.top=(rect.top-r.top)+'px';clone.style.width=r.width+'px';ghost.append(clone);c.classList.add('drag-hidden');});document.body.append(ghost);run.ghost=ghost;run.left=r.left;run.top=r.top;
}
$('#board').addEventListener('dragstart',e=>e.preventDefault());
$('#board').addEventListener('pointerdown',e=>{const c=e.target.closest('[data-index]');if(e.pointerType!=='mouse'||e.button!==0||!c||!movable(state,+c.dataset.column,+c.dataset.index)||state.won)return;dragging={column:+c.dataset.column,index:+c.dataset.index,x:e.clientX,y:e.clientY,moved:false};c.setPointerCapture(e.pointerId);});
$('#board').addEventListener('pointermove',e=>{if(!dragging)return;if(!dragging.moved&&Math.hypot(e.clientX-dragging.x,e.clientY-dragging.y)>6){dragging.moved=true;dragGhost(dragging);}if(!dragging.moved)return;dragging.ghost.style.transform='translate('+(dragging.left+e.clientX-dragging.x)+'px,'+(dragging.top+e.clientY-dragging.y)+'px)';document.querySelectorAll('.drop-target').forEach(c=>c.classList.remove('drop-target'));const col=document.elementFromPoint(e.clientX,e.clientY)?.closest('.column');if(col&&canMove(state,dragging.column,dragging.index,+col.dataset.column))col.classList.add('drop-target');});
$('#board').addEventListener('pointerup',e=>{if(!dragging)return;const run=dragging;dragging=null;if(!run.moved)return;suppressClickUntil=performance.now()+350;const col=document.elementFromPoint(e.clientX,e.clientY)?.closest('.column');motionOrigins=cardPositions();run.ghost.querySelectorAll('.card').forEach(c=>{const r=c.getBoundingClientRect();motionOrigins.set(c.dataset.cardId,{left:r.left,top:r.top,down:false});});clearDrag();if(col&&canMove(state,run.column,run.index,+col.dataset.column)){checkpoint();move(state,run.column,run.index,+col.dataset.column);commit();}else{selected={column:run.column,index:run.index};message='Place this run on the next higher rank, or an empty column.';render();}});
$('#board').addEventListener('pointercancel',()=>{dragging=null;clearDrag();});
$('#deal').addEventListener('click',()=>{if(!canDeal(state)){message='Fill every empty column before dealing.';render();return;}checkpoint();deal(state);commit();});
$('#undo').addEventListener('click',()=>{if(!history.length)return;state=history.pop();commit();});
$('#hint').addEventListener('click',()=>{selected=null;suggested=hint(state);if(suggested){const c=state.columns[suggested.from][suggested.index];message=`Move ${rankLabel(c.rank)}${suitSymbol(c.suit)} from column ${suggested.from+1} to ${suggested.to+1}.`;}else message=canDeal(state)?'No useful move. Deal the next row.':state.stock.length?'Fill the empty columns before dealing. Undo may help.':'No useful move found. Try undo or a new game.';render();});
function saveView(){try{localStorage.setItem('clicks:spider:view',JSON.stringify({wide:$('#board').classList.contains('wide'),scale:viewScale}));}catch{}}
function setView(wide,scale=viewScale){
 if(dragging){dragging=null;clearDrag();}$('#board').querySelectorAll('.card').forEach(c=>c.getAnimations().forEach(a=>a.cancel()));viewScale=scale;$('#board').classList.toggle('wide',wide);$('#zoom').textContent=wide||scale!==1?'Fit all':'Larger cards';$('#zoom').setAttribute('aria-pressed',wide||scale!==1);$('#view-note').textContent=wide||scale>1?'Scroll across to see every column':'Drag or tap to move';$('#card-scale').textContent=Math.round(viewScale*100)+'%';$('#smaller').disabled=viewScale<=zoomSteps[0];$('#larger').disabled=viewScale>=zoomSteps.at(-1);layout();
}
let wide=innerWidth<760;try{const savedView=JSON.parse(localStorage.getItem('clicks:spider:view'));if(typeof savedView?.wide==='boolean')wide=savedView.wide;if(zoomSteps.includes(savedView?.scale))viewScale=savedView.scale;}catch{}setView(wide);
$('#zoom').addEventListener('click',()=>{setView(!$('#board').classList.contains('wide')&&viewScale===1,1);saveView();});
function changeZoom(direction){const next=Math.max(0,Math.min(zoomSteps.length-1,zoomSteps.indexOf(viewScale)+direction));setView($('#board').classList.contains('wide'),zoomSteps[next]);saveView();}
$('#smaller').onclick=()=>changeZoom(-1);$('#larger').onclick=()=>changeZoom(1);
window.addEventListener('resize',scheduleLayout);window.visualViewport?.addEventListener('resize',scheduleLayout);
new ResizeObserver(entries=>{const width=entries[0].contentRect.width;if(Math.abs(width-observedWidth)>.1){observedWidth=width;scheduleLayout();}}).observe($('.table-scroll'));
function start(){state=newGame(Math.floor(Math.random()*4294967296));history=[];elapsed=0;commit();$('#modal').close();}
function requestNew(){if(state.moves&&!state.won){$('#dialog-title').textContent='Start a new game?';$('#dialog-body').innerHTML='<p>Your current game will be replaced.</p><div class="dialog-actions"><button id="cancel-new">Keep playing</button><button id="confirm-new">New game</button></div>';$('#cancel-new').onclick=()=>$('#modal').close();$('#confirm-new').onclick=start;$('#modal').showModal();}else start();}
$('#new').onclick=requestNew;$('#play-again').onclick=start;$('#close').onclick=()=>$('#modal').close();
$('#help').onclick=()=>{$('#dialog-title').textContent='Two-suit Spider';$('#dialog-body').innerHTML='<ul><li>Build down: put a 7 on any 8.</li><li>Move several cards together only when they descend in the same suit.</li><li>Any card or matching run can fill an empty column.</li><li>A King-to-Ace run in one suit clears automatically. Clear all eight to win.</li><li>Deal adds one card to every column. Fill empty columns first.</li></ul><p>Tap a card or run, then its destination. You can also drag on a computer. Undo reverses moves and deals. Progress saves in this browser.</p><p class="credits">Original card artwork · <a href="./cards/ABOUT.txt" target="_blank">About the deck</a>.</p>';$('#modal').showModal();};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){selected=null;suggested=null;message='';render();}});
setInterval(()=>{if(document.hidden||state.won||$('#modal').open)return;elapsed++;$('#time').textContent=timeText();if(elapsed%5===0)save();},1000);
document.addEventListener('visibilitychange',()=>{if(document.hidden)save();});window.addEventListener('pagehide',save);save();render();

for(const suit of ["S","H"])for(let rank=1;rank<=13;rank++){const image=new Image();image.src=cardPath(rank,suit);}
